def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)
        value = value.strip().lower()

        if value.count("@") != 1:
            return ""
        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
        return f"{local}@{domain}"

    def valid_email(email):
        if email.count("@") != 1:
            return False
        local, domain = email.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(value):
        match = re.search(r"x|ext|#", value, flags=re.IGNORECASE)
        if match:
            value = value[:match.start()]
        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]
        if len(value) == 4 and value.isdigit():
            value = "0" + value
        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        if not valid_email(email):
            email = ""
        phone = normalize_phone(row["phone"])
        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "row": row,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": opted_out(row["opted_out"]),
            "tags": [
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            ],
        })

    # Union-find makes identity matching transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_last_owner = {}

    for i, person in enumerate(prepared):
        email = person["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        phone, last_name = person["phone"], person["last_name"]
        if phone and last_name:
            key = (phone, last_name.casefold())
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def pick(group, field, require_valid=False):
        candidates = [
            person for person in group
            if person[field] and (not require_valid or person[field])
        ]
        if not candidates:
            return ""
        winner = min(
            candidates,
            key=lambda person: (
                person["source"] != "manual",
                -person["updated_dt"].timestamp(),
                person["index"],
            ),
        )
        return winner[field]

    output = []
    ordered_groups = sorted(groups.values(), key=lambda group: min(p["index"] for p in group))

    for group in ordered_groups:
        latest = max(person["updated_dt"] for person in group)
        output.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email", require_valid=True),
            "phone": pick(group, "phone", require_valid=True),
            "source": pick(group, "source"),
            "tags": ";".join(sorted({tag for person in group for tag in person["tags"]})),
            "opted_out": "Y" if any(person["opted_out"] for person in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
